import{_ as l,a0 as o,w as a,s as g,I as t,x as e,a1 as s,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"OpenMessaging：構建一個分佈式消息分發開放標準 | LCTT x X-CMD","titleTemplate":false,"description":"OpenMessaging：構建一個分佈式消息分發開放標準 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OpenMessaging：構建一個分佈式消息分發開放標準 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OpenMessaging：構建一個分佈式消息分發開放標準 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171009 Building an Open Standard for Distributed Messaging Introducing OpenMessaging","title":"OpenMessaging：構建一個分佈式消息分發開放標準","tag":"201710","desc":""},"relativePath":"201710/20171009 Building an Open Standard for Distributed Messaging Introducing OpenMessaging.md","filePath":"[post].md"}'),u={name:"201710/20171009 Building an Open Standard for Distributed Messaging Introducing OpenMessaging.md"};function d(M,n,f,m,A,O){const i=o("Link");return a(),g("div",null,[n[22]||(n[22]=t("h1",{id:"openmessaging-構建一個分佈式消息分發開放標準",tabindex:"-1"},[e("OpenMessaging：構建一個分佈式消息分發開放標準 "),t("a",{class:"header-anchor",href:"#openmessaging-構建一個分佈式消息分發開放標準","aria-label":"Permalink to “OpenMessaging：構建一個分佈式消息分發開放標準”"},"​")],-1)),n[23]||(n[23]=t("p",null,"通過在雲計算、大數據和標準 API 上的企業及社區的協作，我很高興 OpenMessaging 項目進入 Linux 基金會。OpenMessaging 社區的目標是為分佈式消息分發創建全球採用的、供應商中立的和開放標準，可以部署在雲端、內部和混合雲情景中。",-1)),n[24]||(n[24]=t("p",null,"阿里巴巴、雅虎、滴滴和 Streamlio 是該項目的創始貢獻者。Linux 基金會已與這個初始項目社區合作來建立一個治理模式和結構，以實現運作在消息 API 標準上的生態系統的長期受益。",-1)),t("p",null,[n[2]||(n[2]=e("由於越來越多的公司和開發者邁向",-1)),n[3]||(n[3]=t("ruby",null,[e("雲原生應用"),t("rt",null,"cloud native application")],-1)),n[4]||(n[4]=e("，消息式應用和流式應用的擴展面臨的挑戰也在不斷發展。這包括平台之間的互操作性問題，",-1)),t("ruby",null,[s(i,{href:"https://en.wikipedia.org/wiki/Wire_protocol"},{default:p(()=>[...n[0]||(n[0]=[e("線路級協議",-1)])]),_:1}),n[1]||(n[1]=t("rt",null,"wire-level protocol",-1))]),n[5]||(n[5]=e("之間缺乏兼容性以及系統間缺乏標準的基準測試。",-1))]),n[25]||(n[25]=t("p",null,"特別是當數據跨不同的消息平台和流平台進行傳輸時會出現兼容性問題，這意味着額外的工作和維護成本。現有解決方案缺乏負載平衡、容錯、管理、安全性和流功能的標準化指南。目前的系統不能滿足現代面向雲的消息應用和流應用的需求。這可能導致開發人員額外的工作，並且難以或不可能滿足物聯網、邊緣計算、智能城市等方面的尖端業務需求。",-1)),n[26]||(n[26]=t("p",null,"OpenMessaging 的貢獻者正在尋求通過以下方式改進分佈式消息分發：",-1)),n[27]||(n[27]=t("ul",null,[t("li",null,"為分佈式消息分發創建一個面向全球、面向雲、供應商中立的行業標準"),t("li",null,"促進用於測試應用程序的標準基準發展"),t("li",null,"支持平台獨立"),t("li",null,"以可伸縮性、靈活性、隔離和安全性為目標的雲數據的流和消息分發要求"),t("li",null,"培育不斷發展的開發貢獻者社區")],-1)),t("p",null,[n[7]||(n[7]=e("你可以在這瞭解有關新項目的更多信息以及如何參與： ",-1)),s(i,{href:"http://openmessaging.cloud/"},{default:p(()=>[...n[6]||(n[6]=[e("http://openmessaging.cloud",-1)])]),_:1}),n[8]||(n[8]=e("。",-1))]),n[28]||(n[28]=r("<p>這些是支持 OpenMessaging 的一些組織：</p><p>“我們多年來一直專注於消息分發和流領域，在此期間，我們探索了 Corba 通知、JMS 和其它標準，來試圖解決我們最嚴格的業務需求。阿里巴巴在評估了可用的替代品後，選擇創建一個新的面向雲的消息分發標準 OpenMessaging，這是一個供應商中立，且語言無關的標準，併為金融、電​​子商務、物聯網和大數據等領域提供了行業指南。此外，它目地在於跨異構系統和平台間開發消息分發和流應用。我們希望它可以是開放、簡單、可擴展和可互操作的。另外，我們要根據這個標準建立一個生態系統，如基準測試、計算和各種連接器。我們希望有新的貢獻，並希望大家能夠共同努力，推動 OpenMessaging 標準的發展。”</p><p>——阿里巴巴高級架構師 Von Gosling，Apache RocketMQ 的聯合創始人，以及 OpenMessaging 的原始發起人</p><p>“隨着應用程序消息的複雜性和規模的不斷擴大，缺乏標準的接口為開發人員和組織帶來了複雜性和靈活性的障礙。Streamlio 很高興與其他領導者合作推出 OpenMessaging 標準倡議來給客户一個輕鬆使用高性能、低延遲的消息傳遞解決方案，如 Apache Pulsar，它提供了企業所需的耐用性、一致性和可用性。“</p><p>—— Streamlio 的軟件工程師、Apache Pulsar 的聯合創始人以及 Apache BookKeeper PMC 的成員 Matteo Merli</p><p>“Oath（Verizon 旗下領先的媒體和技術品牌，包括雅虎和 AOL）支持開放，協作的舉措，並且很樂意加入 OpenMessaging 項目。”</p><p>—— Joe Francis，核心平台總監</p><p>“在滴滴中，我們定義了一組私有的生產者 API 和消費者 API 來隱藏開源的 MQ（如 Apache Kafka、Apache RocketMQ 等）之間的差異，並提供額外的自定義功能。我們計劃將這些發佈到開源社區。到目前為止，我們已經積累了很多關於 MQ 和 API 統一的經驗，並願意在 OpenMessaging 中與其它 API 一起構建 API 的共同標準。我們真誠地認為，統一和廣泛接受的 API 標準可以使 MQ 技術和依賴於它的應用程序受益。”</p><p>—— 滴滴的架構師 Neil Qi_</p><p>“有許多不同的開源消息分發解決方案，包括 Apache ActiveMQ、Apache RocketMQ、Apache Pulsar 和 Apache Kafka。缺乏行業級的可擴展消息分發標準使得評估合適的解決方案變得困難。我們很高興能夠與多個開源項目共同努力，共同確定可擴展的開放消息規範。 Apache BookKeeper 已成功在雅虎（通過 Apache Pulsar）和 Twitter（通過 Apache DistributedLog）的生產環境中部署，它作為其企業級消息系統的持久化、高性能、低延遲存儲基礎。我們很高興加入 OpenMessaging 幫助其它項目解決諸如低延遲持久化、一致性和可用性等在消息分發方案中的常見問題。”</p><p>—— Streamlio 的聯合創始人、Apache BookKeeper 的 PMC 主席、Apache DistributedLog 的聯合創造者，Sijie Guo</p><hr>",12)),t("p",null,[n[10]||(n[10]=e("via: ",-1)),s(i,{href:"https://www.linuxfoundation.org/blog/building-open-standard-distributed-messaging-introducing-openmessaging/"},{default:p(()=>[...n[9]||(n[9]=[e("https://www.linuxfoundation.org/blog/building-open-standard-distributed-messaging-introducing-openmessaging/",-1)])]),_:1})]),t("p",null,[n[14]||(n[14]=e("作者：",-1)),s(i,{href:"https://www.linuxfoundation.org/author/mdolan/"},{default:p(()=>[...n[11]||(n[11]=[e("Mike Dolan",-1)])]),_:1}),n[15]||(n[15]=e(" 譯者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:p(()=>[...n[12]||(n[12]=[e("geekpi",-1)])]),_:1}),n[16]||(n[16]=e(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:p(()=>[...n[13]||(n[13]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[19]||(n[19]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[17]||(n[17]=[e("LCTT",-1)])]),_:1}),n[20]||(n[20]=e(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:p(()=>[...n[18]||(n[18]=[e("Linux中國",-1)])]),_:1}),n[21]||(n[21]=e(" 榮譽推出",-1))])])}const x=l(u,[["render",d]]);export{P as __pageData,x as default};
